'use client';
import {countCharacters,renderPlain} from '../lib/characters';
import { useState,useEffect,useCallback,FormEvent } from 'react';
import { ShieldCheck,LayoutDashboard,Newspaper,Radio,Layers3,FileText,FlaskConical,History,Clock,Users,Settings,ChevronRight,Search,Plus,Upload,RefreshCw,ArrowUpRight,Mail,Copy,Download,Check,CheckCircle2,AlertCircle,ArrowLeft,LogOut,X,Zap,Lock,Globe,Calendar,ArrowRight,Loader2,Send,Eye,Menu,ChevronDown,ArrowUp,ArrowDown } from 'lucide-react';

type Obj=Record<string,any>;
const NAV=[['overview','Обзор',LayoutDashboard],['articles','Материалы',Newspaper],['sources','Источники',Radio],['events','События',Layers3],['digests','Дайджесты',FileText],['journal','Журнал',History],['schedules','Расписание',Clock],['subscribers','Подписчики',Users],['settings','Настройки',Settings]] as const;
const STATUS:Record<string,string>={queued:'В очереди',running:'Обрабатывается',succeeded:'Завершено',partially_succeeded:'Частично завершено',failed:'Ошибка',cancelled:'Отменено',needs_review:'На проверке',validation_failed:'Нужны исправления',approved:'Утверждён',draft:'Черновик',included:'Включено',excluded:'Исключено',not_selected:'Не выбрано',candidate:'Кандидат',passed:'Пройдена',not_run:'Не запускалась'};
const fmt=(s:string)=>s?new Date(s).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+' МСК':'Не подтверждена';
const kind=(s:string)=>s==='test'?'Архивный набор':s==='live'?'Живой сбор':'Набор организаторов';

function Badge({status,children}:{status?:string,children?:React.ReactNode}){return <span className={'badge '+(status||'neutral')}><span className="badge-dot"/>{children||STATUS[status||'']||status}</span>}
function Empty({icon:Icon=FileText,title,text,action}:{icon?:any,title:string,text:string,action?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><Icon size={25}/></div><h3>{title}</h3><p>{text}</p>{action}</div>}

export default function Home(){
 const [user,setUser]=useState<Obj|null>(null),[csrf,setCsrf]=useState(''),[authReady,setAuthReady]=useState(false);
 const [view,setView]=useState('overview'),[data,setData]=useState<Obj|null>(null),[sources,setSources]=useState<Obj[]>([]),[articles,setArticles]=useState<Obj[]>([]),[articleTotal,setArticleTotal]=useState(0),[articleOffset,setArticleOffset]=useState(0),[tests,setTests]=useState<Obj|null>(null),[schedules,setSchedules]=useState<Obj[]>([]),[subscribers,setSubscribers]=useState<Obj[]>([]),[settings,setSettings]=useState<Obj|null>(null);
 const [datasetId,setDatasetId]=useState(''),[control,setControl]=useState(()=>new Date().toLocaleString('sv-SE',{timeZone:'Europe/Moscow'}).replace(' ','T').slice(0,16)),[query,setQuery]=useState(''),[selectedDigest,setSelectedDigest]=useState<Obj|null>(null),[run,setRun]=useState<Obj|null>(null),[digestTab,setDigestTab]=useState('full'),[modal,setModal]=useState<string|null>(null),[detail,setDetail]=useState<Obj|null>(null),[busy,setBusy]=useState(false),[toast,setToast]=useState<Obj|null>(null),[activeJob,setActiveJob]=useState<Obj|null>(null),[loginError,setLoginError]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[models,setModels]=useState<string[]>([]),[editing,setEditing]=useState(false),[editedItems,setEditedItems]=useState<Obj[]>([]);
 const [groupSelection,setGroupSelection]=useState<string[]>([]);
 const canEdit=user?.role!=='viewer';
 useEffect(()=>{
  if(!modal)return;
  const previous=document.activeElement as HTMLElement|null;
  const oldOverflow=document.body.style.overflow;
  document.body.style.overflow='hidden';
  const dialog=document.querySelector('.modal');
  const elements=()=>Array.from(dialog?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')||[]);
  elements()[0]?.focus();
  const keys=(event:KeyboardEvent)=>{
   if(event.key==='Escape'){setModal(null);return}
   if(event.key!=='Tab')return;
   const list=elements();const first=list[0];const last=list[list.length-1];
   if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}
   else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}
  };
  document.addEventListener('keydown',keys);
  return()=>{document.body.style.overflow=oldOverflow;document.removeEventListener('keydown',keys);previous?.focus()};
 },[modal]);

 const notify=useCallback((message:string,error=false)=>{setToast({message,error});setTimeout(()=>setToast(null),6000)},[]);
 const api=useCallback(async(path:string,options:RequestInit={})=>{
  const headers:Record<string,string>={'X-CSRF-Token':csrf};
  if(!(options.body instanceof FormData))headers['Content-Type']='application/json';
  const response=await fetch('/api/v1'+path,{...options,credentials:'include',headers:{...headers,...options.headers}});
  const result=await response.json().catch(()=>({detail:'Не удалось прочитать ответ сервера'}));
  if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'Проверьте заполненные поля');
  return result;
 },[csrf]);
 useEffect(()=>{fetch('/api/v1/auth/me').then(async r=>{if(r.ok){const m=await r.json();setUser(m.user);setCsrf(m.csrf)}}).finally(()=>setAuthReady(true))},[]);
 const reload=useCallback(async()=>{if(!user)return;const o=await api('/overview');setData(o);if(!datasetId&&o.datasets.length){setDatasetId(o.datasets[0].id);if(o.datasets[0].meta?.control_time)setControl(o.datasets[0].meta.control_time.slice(0,16))}if(selectedDigest){const d=await api('/digests/'+selectedDigest.id);setSelectedDigest(d)}} ,[user,api,datasetId,selectedDigest?.id]);
 useEffect(()=>{if(user)reload().catch(e=>notify(e.message,true))},[user]);
 useEffect(()=>{
  if(!user)return;
  let valid=true;
  const load=async()=>{
   if(view==='sources'){const r=await api('/sources');if(valid)setSources(r)}
   if(view==='articles'){const r=await api('/articles?dataset_id='+datasetId+'&query='+encodeURIComponent(query)+'&offset='+articleOffset);if(valid){setArticles(r.items);setArticleTotal(r.total)}}
   if(view==='tests'){const r=await api('/tests');if(valid)setTests(r)}
   if(view==='schedules'){const r=await api('/schedules');if(valid)setSchedules(r)}
   if(view==='subscribers'){const r=await api('/subscribers');if(valid)setSubscribers(r)}
   if(view==='settings'){const r=await api('/settings');if(valid)setSettings(r)}
  };load().catch(e=>notify(e.message,true));return()=>{valid=false};
 },[view,user,datasetId,query,articleOffset,api,data]);
 useEffect(()=>{if(!activeJob||!['queued','running'].includes(activeJob.status))return;const timer=setInterval(async()=>{
  try{const j=await api('/jobs/'+activeJob.id);setActiveJob(j);if(!['queued','running'].includes(j.status)){await reload();if(j.result?.digest_id){const d=await api('/digests/'+j.result.digest_id);setSelectedDigest(d);setView('digests');setRun(await api('/runs/'+d.run_id))}if(j.result?.dataset_id)setDatasetId(j.result.dataset_id);if(j.error)notify(j.error,true);else notify('Обработка завершена')}}catch(e:any){notify(e.message,true)}
 },1500);return()=>clearInterval(timer)},[activeJob?.id,activeJob?.status,api,reload,notify]);
 const action=async(fn:()=>Promise<any>,message?:string)=>{setBusy(true);try{const r=await fn();if(r?.id&&r?.kind)setActiveJob(r);if(message)notify(message);await reload();return r}catch(e:any){notify(e.message,true);return null}finally{setBusy(false)}};
 const post=(path:string,body:Obj={})=>api(path,{method:'POST',body:JSON.stringify(body)});
 const patch=(path:string,body:Obj)=>api(path,{method:'PATCH',body:JSON.stringify(body)});
 const navigate=(v:string)=>{setView(v);setMobileMenu(false);setEditing(false)};
 const chooseDigest=async(d:Obj)=>{setSelectedDigest(d);setDigestTab('full');setRun(await api('/runs/'+d.run_id));navigate('digests')};
 const ensureRun=async()=>{const d=selectedDigest||data?.digests?.[0];if(d){if(!selectedDigest)setSelectedDigest(d);setRun(await api('/runs/'+d.run_id))}};
 useEffect(()=>{if(user&&['events','journal'].includes(view))ensureRun().catch(e=>notify(e.message,true))},[view,selectedDigest?.id,data?.digests?.length]);
 const generate=()=>action(()=>post('/processing-runs',{dataset_id:datasetId,control_time:control+':00+03:00',idempotency_key:crypto.randomUUID()}));
 const login=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);try{const r=await post('/auth/login',{email:f.get('email'),password:f.get('password')});setCsrf(r.csrf);setUser(r.user);setLoginError('')}catch(e:any){setLoginError(e.message)}finally{setBusy(false)}};
 const submitModal=async(e:FormEvent<HTMLFormElement>)=>{
  e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));
  const r=await action(async()=>{
   if(modal==='import'){const body=new FormData();body.append('file',f.file as File);body.append('metadata',JSON.stringify({name:f.name||undefined,mapping:JSON.parse(String(f.mapping||'{}')),encoding:f.encoding||'utf-8-sig',assume_moscow:f.assume_moscow==='on',id:f.id||undefined,title:f.title||undefined,source:f.source||undefined,url:f.url||undefined,published_at:f.published_at?String(f.published_at)+':00+03:00':undefined}));return api('/datasets/import',{method:'POST',body})}
   if(modal==='manual')return post('/articles/manual',{...f,published_at:f.published_at?f.published_at+':00+03:00':null});
   if(modal==='url')return post('/articles/url',{...f,idempotency_key:crypto.randomUUID()});
   if(modal==='subscriber')return post('/subscribers',f);
   if(modal==='schedule'){const [h,m]=String(f.time).split(':');return post('/schedules',{name:f.name,dataset_id:f.dataset_id,hour:Number(h),minute:Number(m)})}
   if(modal==='send')return post('/digests/'+selectedDigest?.id+'/send',{recipient:f.recipient});
  },'Действие выполнено');if(r){if(r.dataset_id)setDatasetId(r.dataset_id);setModal(null)}
 };
 const currentDataset=data?.datasets?.find((d:Obj)=>d.id===datasetId);
 const latest=data?.digests?.[0];
 const copy=async(text:string)=>{try{await navigator.clipboard.writeText(text);notify('Текст скопирован')}catch{notify('Браузер не разрешил копирование. Используйте экспорт.',true)}};

 if(!authReady)return <main className="login-shell"><Loader2 className="spin"/></main>;
 if(!user)return <main className="login-shell"><div className="login-art"><div className="brand"><div className="logo"><ShieldCheck/></div>КиберСводка</div><div><span className="eyebrow">РЕДАКЦИЯ КИБЕРБЕЗОПАСНОСТИ</span><h1>От публикаций<br/>к проверяемому<br/>дайджесту.</h1><p>События, последствия и источники.<br/>В одном рабочем кабинете.</p><div className="login-points"><span><Check size={17}/> До пяти событий за сутки</span><span><Check size={17}/> Каждый факт с источником</span><span><Check size={17}/> Письмо и короткий пост</span></div></div><small>КиберСводка · Ежедневная редакция</small></div><section className="login-form"><div><span className="pill">РАБОЧИЙ КАБИНЕТ</span><h2>Войти в редакцию</h2><p>Продолжите работу с материалами и выпусками.</p><form onSubmit={login}><label>Email<input name="email" type="email" autoComplete="username" required placeholder="Ваш email"/></label><label>Пароль<input name="password" type="password" autoComplete="current-password" required placeholder="Ваш пароль"/></label>{loginError&&<div className="error-box">{loginError}</div>}<button className="btn primary wide" disabled={busy}>{busy?<Loader2 className="spin" size={17}/>:<ArrowRight size={17}/>} Войти</button></form></div></section>{toast&&<div className={'toast '+(toast.error?'error':'')}>{toast.message}</div>}</main>;

 return <div className="app-shell">
  <aside className={'sidebar '+(mobileMenu?'open':'')}><button className="brand" onClick={()=>navigate('overview')}><div className="logo"><ShieldCheck size={22}/></div><span>КиберСводка<small>редакция новостей ИБ</small></span></button><button className="mobile-only mobile-sidebar-close" aria-label="Закрыть меню" onClick={()=>setMobileMenu(false)}>Закрыть меню <X size={16}/></button><div className="workspace"><div className="workspace-symbol">К</div><div><b>Рабочее пространство</b><small>Новостная редакция</small></div><ChevronDown size={14}/></div><div className="nav-caption">РАБОЧИЙ КАБИНЕТ</div><nav>{NAV.map(([id,label,Icon])=><button key={id} className={view===id?'active':''} onClick={()=>navigate(id)}><Icon size={18}/><span>{label}</span>{id==='articles'&&<span className="nav-number">{data?.counts?.articles||0}</span>}{id==='digests'&&latest?.status==='needs_review'&&<span className="nav-pip"/>}</button>)}</nav><div className="sidebar-bottom"><div className="local-note"><span className="status-dot"/><span>{data?.integrations?.app_env==='server'?'Сервер подключён':'Локальная среда'}</span><Lock size={12}/></div><div className="profile"><div className="avatar">{user.role==='viewer'?'Д':'Р'}</div><div><b>{user.role==='viewer'?'Наблюдатель':'Редактор'}</b><small>{user.email}</small></div><button title="Выйти" onClick={()=>action(async()=>{await post('/auth/logout');setUser(null);setData(null)})}><LogOut size={17}/></button></div></div></aside>
  <div className="main-wrap"><header className="topbar"><button className="icon-button mobile-only" aria-label="Открыть меню" onClick={()=>setMobileMenu(!mobileMenu)}><Menu size={21}/></button><div className="breadcrumbs">Рабочий кабинет <ChevronRight size={13}/><b>{NAV.find(n=>n[0]===view)?.[1]}</b></div><div className="topbar-right"><span className="timezone"><Clock size={14}/> Europe/Moscow</span><span className="outline-pill">Редакция</span><button className="icon-button" title="Обновить данные" onClick={()=>action(reload)}><RefreshCw size={17}/></button></div></header>
  <main className="content">
   <div className="page-heading"><div><div className="eyebrow">{view==='overview'?'НОВОСТНАЯ РЕДАКЦИЯ':'КИБЕРСВОДКА'}</div><h1>{view==='overview'?'Обзор редакции':NAV.find(n=>n[0]===view)?.[1]}</h1><p>{({overview:'Отберите важное. Проверьте факты. Подготовьте выпуск.',articles:'Исходные публикации, метаданные и решения по каждой записи.',sources:'Согласованные сайты и состояние реального сбора.',events:'Один инцидент - одна группа. Все публикации остаются доступны.',digests:'Полный выпуск, предпросмотр письма и сокращённый пост.',tests:'Восемь обязательных сценариев. Входы, ответы и результаты.',journal:'Почему материал включён, объединён или исключён.',schedules:'Ежедневные черновики по московскому времени.',subscribers:'Подписчики, получающие утверждённые выпуски.',settings:'Интеграции, параметры обработки и безопасная конфигурация.'} as Obj)[view]}</p></div><div className="heading-actions">{view==='overview'&&<><button className="btn" disabled={!canEdit||busy} onClick={()=>action(()=>post('/collection-runs',{idempotency_key:crypto.randomUUID()}))}><RefreshCw size={16}/> Собрать новости</button><button className="btn" disabled={!canEdit} onClick={()=>setModal('import')}><Upload size={16}/> Загрузить материалы</button><button className="btn primary" disabled={!datasetId||busy||!canEdit} onClick={generate}><Zap size={16}/> Новый дайджест</button></>}{view==='articles'&&<><button className="btn" disabled={!canEdit} onClick={()=>setModal('url')}><Globe size={16}/> По ссылке</button><button className="btn" disabled={!canEdit} onClick={()=>setModal('manual')}><Plus size={16}/> Вручную</button><button className="btn primary" disabled={!canEdit} onClick={()=>setModal('import')}><Upload size={16}/> Импорт</button></>}{view==='subscribers'&&<button className="btn primary" disabled={!canEdit} onClick={()=>setModal('subscriber')}><Plus size={16}/> Добавить адрес</button>}{view==='schedules'&&<button className="btn primary" disabled={!canEdit} onClick={()=>setModal('schedule')}><Plus size={16}/> Добавить расписание</button>}</div></div>

   {activeJob&&<div className={'job-strip '+(activeJob.status==='failed'?'failed':'')}><div className="job-icon">{['running','queued'].includes(activeJob.status)?<Loader2 className="spin" size={20}/>:activeJob.status==='failed'?<AlertCircle size={20}/>:<CheckCircle2 size={20}/>}</div><div><b>{activeJob.stage}</b><small>{activeJob.error||STATUS[activeJob.status]}</small></div><div className="progress-track"><span style={{width:activeJob.progress+'%'}}/></div><b className="percent">{activeJob.progress}%</b>{['queued','running'].includes(activeJob.status)?<button className="btn tiny" onClick={()=>action(()=>post('/jobs/'+activeJob.id+'/cancel'))}>Отменить</button>:<button className="icon-button" aria-label="Закрыть статус" onClick={()=>setActiveJob(null)}><X size={16}/></button>}</div>}

   {view==='overview'&&<>
    <section className="period-panel"><div className="period-icon"><Calendar size={21}/></div><div className="period-label"><b>Период выпуска</b><small>Последние 24 часа до контрольного времени</small></div><div className="period-controls"><label>Набор материалов<select aria-label="Набор материалов" value={datasetId} onChange={e=>{setDatasetId(e.target.value);setArticleOffset(0);const d=data?.datasets?.find((d:Obj)=>d.id===e.target.value);if(d?.meta?.control_time)setControl(d.meta.control_time.slice(0,16))}}><option value="">Выберите набор</option>{data?.datasets?.map((d:Obj)=><option value={d.id} key={d.id}>{d.name}</option>)}</select></label><label>Контрольное время, МСК<input aria-label="Контрольное время" type="datetime-local" value={control} onChange={e=>setControl(e.target.value)}/></label></div></section>
    <div className="stats-grid">{[[Newspaper,'Материалы',currentDataset?.article_count??data?.counts?.articles??0,'Публикации в выбранном наборе'],[Layers3,'События',latest?.data?.event_count??0,'В последнем выпуске'],[FileText,'Выпуски',data?.counts?.digests??0,'Сохранены в истории'],[Radio,'Источники',data?.counts?.sources??0,'Согласованы и включены']].map(([Icon,label,note,sub]:any)=><div className="stat-card" key={label}><div className="stat-top"><span>{label}</span><Icon size={18}/></div><b>{note}</b><small>{sub}</small></div>)}</div>
    <div className="overview-grid"><section className="panel latest-panel"><div className="panel-head"><div><span className="eyebrow">ПОСЛЕДНИЙ ВЫПУСК</span><h2>{latest?'Дайджест по кибербезопасности':'Создайте первый дайджест'}</h2></div>{latest&&<Badge status={latest.status}/>}</div>{latest?<><div className="digest-meta"><Calendar size={14}/>{latest.data.period}<span>·</span>{latest.data.event_count} события<span>·</span>Обработано GigaChat</div><div className="event-teasers">{latest.data.items.map((item:Obj,i:number)=><button className="event-teaser" key={item.event_id} onClick={()=>chooseDigest(latest)}><span className="event-number">0{i+1}</span><div><h3>{item.title.text}</h3><p>{item.summary[0]?.text}</p><small><span className="source-dot"/>{latest.data.events[i]?.sources.length} источника · {latest.data.events[i]?.conflicts.length?'Есть расхождения':'Фрагменты источников сохранены'}</small></div><ArrowUpRight size={18}/></button>)}</div><div className="panel-footer"><span><ShieldCheck size={15}/> {latest.validation.passed?'Автоматические проверки пройдены':'Требуется исправление'}</span><button className="btn primary" onClick={()=>chooseDigest(latest)}>Открыть выпуск <ArrowRight size={15}/></button></div></>:<Empty title="Редакция готова к работе" text="Соберите новости из подключённых источников или загрузите свои материалы." action={<button className="btn primary" disabled={!canEdit||busy} onClick={()=>action(()=>post('/collection-runs',{idempotency_key:crypto.randomUUID()}))}><RefreshCw size={16}/> Собрать новости</button>}/>}</section><div className="overview-rail"><section className="panel workflow-card"><div className="panel-head"><h2>Как устроен выпуск</h2><ShieldCheck size={20}/></div>{[['01','Материалы','Файлы или согласованные источники'],['02','События','Классификация и объединение'],['03','Отбор','Последствия, масштаб, срочность'],['04','Проверка','Факты, период, источники'],['05','Выпуск','Письмо, пост и журнал']].map(([n,t,d])=><div className="workflow-step" key={n}><span>{n}</span><div><b>{t}</b><small>{d}</small></div></div>)}</section><section className="panel integration-card"><div className="integration-heading"><div className="giga-symbol">G</div><div><b>GigaChat API</b><small>{data?.integrations?.model||'Модель не выбрана'}</small></div><span className={'status-dot '+(!data?.integrations?.gigachat?'muted':'')}/></div><p>{data?.integrations?.gigachat?'Ключ настроен. Доступ к модели проверяется отдельно.':'Подключите модель для работы с реальными публикациями.'}</p><button className="text-button" onClick={()=>navigate('settings')}>Настройки интеграции <ArrowRight size={14}/></button></section></div></div>
    <section className="panel runs-panel"><div className="panel-head"><h2>Последние операции</h2><span className="muted">История обработки</span></div>{data?.jobs?.length?<div className="table-wrap"><table><thead><tr><th>Операция</th><th>Начало</th><th>Этап</th><th>Статус</th><th/></tr></thead><tbody>{data.jobs.slice(0,5).map((j:Obj)=><tr key={j.id}><td><b>{{process:'Подготовка дайджеста',daily:'Сбор и подготовка выпуска',tests:'Обязательные проверки',collect:'Сбор источника',url:'Загрузка по ссылке',email:'Письмо'}[j.kind as string]||j.kind}</b></td><td>{fmt(j.created_at)}</td><td>{j.stage}</td><td><Badge status={j.status}/></td><td><button className="icon-button" title="Открыть результат задачи" onClick={()=>{setDetail(j);setModal('job')}}><ArrowUpRight size={16}/></button></td></tr>)}</tbody></table></div>:<div className="simple-empty">История появится после первого импорта или запуска.</div>}</section>
   </>}

   {view==='articles'&&<section className="panel"><div className="filter-bar"><div className="search-field"><Search size={17}/><input placeholder="Поиск по заголовку" value={query} onChange={e=>{setQuery(e.target.value);setArticleOffset(0)}}/></div><select value={datasetId} onChange={e=>{setDatasetId(e.target.value);setArticleOffset(0)}}><option value="">Все наборы</option>{data?.datasets?.map((d:Obj)=><option key={d.id} value={d.id}>{d.name}</option>)}</select><span className="muted">{articleTotal} материалов</span></div>{articles.length?<><div className="table-wrap"><table className="article-table"><thead><tr><th>ID</th><th>Публикация</th><th>Источник</th><th>Дата, МСК</th><th>Данные</th></tr></thead><tbody>{articles.map(a=><tr key={a.internal_id} onClick={()=>{setDetail(a);setModal('article')}} className="clickable"><td><code>{a.id}</code></td><td><b>{a.title||'Заголовок не указан'}</b><small>{a.text.slice(0,90)||'Основного текста нет'}</small></td><td>{a.source||'Не указан'}</td><td>{fmt(a.published_at)}</td><td><Badge status={a.date_status==='CONFIRMED'?'passed':'needs_review'}>{a.text.length<60?'Мало данных':a.date_status==='CONFIRMED'?'Дата подтверждена':'Проверьте дату'}</Badge></td></tr>)}</tbody></table></div><div className="pagination"><span>{articleOffset+1}–{Math.min(articleOffset+articles.length,articleTotal)} из {articleTotal}</span><button className="btn tiny" disabled={!articleOffset} onClick={()=>setArticleOffset(Math.max(0,articleOffset-50))}>Назад</button><button className="btn tiny" disabled={articleOffset+50>=articleTotal} onClick={()=>setArticleOffset(articleOffset+50)}>Далее</button></div></>:<Empty icon={Newspaper} title="Материалы ещё не загружены" text="Импортируйте JSON, JSONL, CSV, TXT, HTML или DOCX. Исходные ID и пропуски будут сохранены." action={<button className="btn" disabled={!canEdit} onClick={()=>setModal('import')}>Загрузить материалы</button>}/>}</section>}

   {view==='sources'&&<><div className="notice"><ShieldCheck size={17}/><span>Проверка адаптера и согласование источника - разные действия. Сбор выполняется только после включения редактором.</span></div><div className="sources-grid">{sources.map(s=><section className="panel source-card" key={s.id}><div className="source-top"><div className="source-logo">{s.name.slice(0,2)}</div><div><h3>{s.name}</h3><a href={s.url} target="_blank" rel="noreferrer">{new URL(s.url).hostname} <ArrowUpRight size={11}/></a></div><label className="switch" title={s.agreed?'Включить/отключить сбор':'Сначала согласуйте'}><input type="checkbox" checked={s.enabled} disabled={!canEdit||!s.agreed} onChange={e=>action(()=>patch('/sources/'+s.id,{enabled:e.target.checked}))}/><span/></label></div><div className="source-state"><Badge status={s.meta.verification_status==='verified'?'passed':s.meta.verification_status==='date_conflict'?'needs_review':'neutral'}>{s.meta.verification_status==='verified'?'RSS проверен':s.meta.verification_status==='date_conflict'?'Расхождение дат':s.feed_url?'Требует проверки':'Не настроен'}</Badge><span>{s.publisher_type==='vendor'?'Производитель':s.publisher_type==='platform'?'Автор площадки':'Редакция СМИ'}</span></div><p>{s.meta.verification_status==='date_conflict'?'Даты RSS и HTML расходятся. Материалы требуют проверки времени.':s.feed_url?'RSS и извлечение полного текста. Ошибки фиксируются отдельно.':'Источник есть в реестре. Для сбора нужен проверенный адаптер.'}</p><div className="source-details"><span>Последний сбор</span><b>{s.last_checked?fmt(s.last_checked):'Не запускался'}</b></div><div className="source-auto"><label><input type="checkbox" disabled={!canEdit||!s.enabled} checked={!!s.meta.auto_collect} onChange={e=>action(()=>patch('/sources/'+s.id,{auto_collect:e.target.checked,collect_interval_minutes:60}))}/><span>Автосбор каждый час</span></label></div><div className="source-actions"><button className="btn tiny" disabled={!canEdit||s.enabled} onClick={()=>action(()=>patch('/sources/'+s.id,{agreed:!s.agreed}))}>{s.agreed?<Check size={14}/>:<Plus size={14}/>} {s.agreed?'Согласован':'Согласовать'}</button><button className="btn tiny" disabled={!canEdit||!s.enabled||(!s.feed_url&&!s.meta.adapter?.endsWith('html'))} onClick={()=>action(()=>post('/sources/'+s.id+'/collect',{limit:3,idempotency_key:crypto.randomUUID()}))}><RefreshCw size={14}/> Собрать</button></div></section>)}</div></>}

   {view==='events'&&<>{run?<><div className="notice subtle"><Layers3 size={17}/><span>Запуск {run.id.slice(0,8)} · {fmt(run.control_time)} · {run.events.length} самостоятельных событий.</span></div><div className="group-toolbar"><span className="muted">Выбрано групп: {groupSelection.length}</span><button className="btn tiny" disabled={!canEdit||groupSelection.length<2||run.events.some((e:Obj)=>!e.candidate_ids)} onClick={()=>action(()=>post('/runs/'+run.id+'/regroup',{operation:'merge',event_ids:groupSelection,reason:'Редактор проверил, что материалы описывают одно событие',idempotency_key:crypto.randomUUID()}))}><Layers3 size={15}/> Объединить выбранные</button><button className="text-button" onClick={()=>{setGroupSelection([]);navigate('digests');setSelectedDigest(null)}}>Открыть историю группировки</button></div>{run.events.map((e:Obj)=><section className="panel event-full" key={e.event_id}><div className="panel-head"><div className="event-heading"><input className="event-checkbox" type="checkbox" aria-label={'Выбрать '+e.title} checked={groupSelection.includes(e.event_id)} onChange={x=>setGroupSelection(old=>x.target.checked?[...old,e.event_id]:old.filter(id=>id!==e.event_id))}/><span className="event-number">{String(e.rank).padStart(2,'0')}</span><div><h2>{e.title}</h2><small>{e.event_id} · {e.sources.length} публикации · {e.independent_origin_count??'неизвестно'} исходных заявлений</small></div></div><Badge status={e.selected?'included':'not_selected'}/></div><div className="event-body"><p>{e.group_reason}</p>{e.conflicts.length>0&&<div className="notice"><AlertCircle size={17}/>{e.conflicts.join(' ')}</div>}<div className="score-grid">{[['Последствия',e.ranking.impact],['Масштаб',e.ranking.scale],['Срочность',e.ranking.urgency],['Для аудитории',e.ranking.audience]].map(([label,value])=><div key={label}><small>{label}</small><b>{value==null?'Нет данных':value+' / 5'}</b></div>)}</div><p className="selection-reason"><b>Почему выбрано:</b> {e.ranking.reason}</p><div className="source-links">{e.sources.map((s:Obj)=><a key={s.id} href={s.url} target="_blank" rel="noreferrer">{s.source} · {s.id} <ArrowUpRight size={13}/></a>)}</div><button className="btn tiny" onClick={()=>{setDetail(e);setModal('evidence')}}><ShieldCheck size={15}/> Проверить факты ({e.claims.length})</button> <button className="btn tiny" disabled={!canEdit||!e.candidate_ids||e.candidate_ids.length<2||run.events.some((x:Obj)=>!x.candidate_ids)} onClick={()=>action(()=>post('/runs/'+run.id+'/regroup',{operation:'split',event_ids:[e.event_id],reason:'Редактор разделил сообщения на самостоятельные события',idempotency_key:crypto.randomUUID()}))}><Layers3 size={15}/> Разделить группу</button></div></section>)}</>:<Empty icon={Layers3} title="События ещё не сформированы" text="Запустите обработку набора. Все связи с исходными публикациями будут сохранены."/>}</>}

   {view==='digests'&&<>{!selectedDigest?<section className="panel">{data?.digests?.length?<div className="digest-list">{data.digests.map((d:Obj)=><button key={d.id} onClick={()=>chooseDigest(d)}><div className="digest-list-icon"><FileText size={23}/></div><div><h3>{d.data.title}</h3><p>{d.data.period}</p><small>{d.data.event_count} событий · GigaChat · Ревизия {d.revision}</small></div><Badge status={d.status}/><ArrowRight size={18}/></button>)}</div>:<Empty title="Пока нет выпусков" text="Выберите материалы и контрольное время в разделе «Обзор»." action={<button className="btn" onClick={()=>navigate('overview')}>Перейти к обработке</button>}/>}</section>:<>
    <div className="digest-toolbar"><button className="text-button" onClick={()=>setSelectedDigest(null)}><ArrowLeft size={15}/> Все выпуски</button><div><Badge status={selectedDigest.status}/><span className="muted">Ревизия {selectedDigest.revision}</span><button className="btn tiny" disabled={!canEdit||busy} onClick={()=>action(async()=>{const d=await post('/digests/'+selectedDigest.id+'/validate');setSelectedDigest(d)})}><ShieldCheck size={15}/> Проверить</button><button className="btn tiny primary" disabled={!canEdit||!selectedDigest.validation.passed||selectedDigest.status==='approved'} onClick={()=>action(async()=>{const d=await post('/digests/'+selectedDigest.id+'/approve');setSelectedDigest(d)},'Выпуск утверждён редактором')}><Check size={15}/> Утвердить</button><a className="btn tiny" href={'/api/v1/digests/'+selectedDigest.id+'/export?format=zip'}><Download size={15}/> Скачать ZIP</a></div></div>
    <div className="digest-workspace"><section className="panel digest-editor"><div className="tabs">{[['full','Дайджест'],['email','Письмо'],['post','Пост'],['facts','Факты'],['reason','Отбор']].map(([id,label])=><button key={id} className={digestTab===id?'active':''} onClick={()=>{setDigestTab(id);setEditing(false)}}>{label}</button>)}</div><div className="editor-top"><span className="outline-pill">{digestTab==='post'?'КОРОТКИЙ ФОРМАТ':digestTab==='email'?'ПРЕДПРОСМОТР ПИСЬМА':'РЕДАКТОР ВЫПУСКА'}</span><div>{['full','post'].includes(digestTab)&&<button className="icon-button" title="Копировать текст" onClick={()=>copy(selectedDigest.data[digestTab==='post'?'post':'full'])}><Copy size={16}/></button>}<a className="icon-button" title="Скачать текст" href={'/api/v1/digests/'+selectedDigest.id+'/export?format='+((({email:'eml',post:'post'} as Obj)[digestTab])||'txt')}><Download size={16}/></a></div></div>
    {digestTab==='email'?<div className="email-preview"><div className="email-fields"><div><span>Тема</span><b>{selectedDigest.data.subject}</b></div><div><span>Получатель</span><span>Активный подписчик или разрешённый адрес</span></div></div><iframe title="Предпросмотр письма" sandbox="allow-same-origin" src={'/api/v1/digests/'+selectedDigest.id+'/preview/email'}/></div>:digestTab==='facts'?<div className="editor-body">{selectedDigest.data.events.map((e:Obj)=><div key={e.event_id} className="facts-section"><h3>{e.title}</h3>{e.claims.map((c:Obj)=><div className="fact-row" key={c.claim_id}><ShieldCheck size={17}/><div><b>{c.text}</b><blockquote>{c.quote}</blockquote><small>ID {c.article_id} · Фрагмент {c.start_offset}–{c.end_offset} · Цитата и числа проверены</small></div></div>)}</div>)}</div>:digestTab==='reason'?<div className="editor-body">{selectedDigest.data.events.map((e:Obj)=><div className="reason-item" key={e.event_id}><h3>{e.rank}. {e.title}</h3><p>{e.ranking.reason}</p><small>Оценка: {e.score.toFixed(2)} / 5 · Масштаб {e.ranking.scale==null?'неизвестен':e.ranking.scale+'/5'}</small></div>)}<p>{selectedDigest.data.zero_events_reason}</p></div>:editing?<div className="editor-body">{editedItems.map((item:Obj,i:number)=><div className="edit-item" key={item.event_id}><label>Заголовок<input value={item.title.text} onChange={e=>setEditedItems(old=>old.map((x,n)=>n===i?{...x,title:{...x.title,text:e.target.value}}:x))}/></label><label>Суть<textarea rows={3} value={item.summary.map((s:Obj)=>s.text).join('\n')} onChange={e=>setEditedItems(old=>old.map((x,n)=>n===i?{...x,summary:e.target.value.split('\n').map((t,j)=>({text:t,claim_ids:x.summary[j]?.claim_ids||x.title.claim_ids}))}:x))}/></label><label>Последствия<textarea value={item.consequences.text} onChange={e=>setEditedItems(old=>old.map((x,n)=>n===i?{...x,consequences:{...x.consequences,text:e.target.value}}:x))}/></label><label>Короткий пост<textarea value={item.short.text} onChange={e=>setEditedItems(old=>old.map((x,n)=>n===i?{...x,short:{...x.short,text:e.target.value}}:x))}/></label></div>)}<div className="button-row"><button className="btn primary" onClick={()=>action(async()=>{const d=await patch('/digests/'+selectedDigest.id+'/draft',{items:editedItems});setSelectedDigest(d);setEditing(false)},'Правки сохранены. Проверьте выпуск повторно.')}>Сохранить ревизию</button><button className="btn" onClick={()=>setEditing(false)}>Отменить</button></div></div>:<article className="editor-body"><span className="digest-kicker">КИБЕРБЕЗОПАСНОСТЬ · ЕЖЕДНЕВНЫЙ ВЫПУСК</span><h2>{selectedDigest.data.title}</h2><p className="digest-period">{selectedDigest.data.period}<br/>Контрольное время: {fmt(selectedDigest.data.control_time)}</p><div className="digest-rule"/>{!selectedDigest.data.items.length&&<p>Подходящих событий за период нет. {selectedDigest.data.zero_events_reason}</p>}{selectedDigest.data.items.map((item:Obj,i:number)=><section className="digest-story" key={item.event_id}><div className="story-heading"><span>{String(i+1).padStart(2,'0')}</span><h3>{item.title.text}</h3></div><p>{digestTab==='post'?item.short.text:item.summary.map((s:Obj)=>s.text).join(' ')}</p>{digestTab==='full'&&<p><b>Последствия.</b> {item.consequences.text}</p>}{selectedDigest.data.events[i].status_notes?.length>0&&<p className="story-status"><b>Статус сообщения.</b> {selectedDigest.data.events[i].status_notes.map((n:Obj)=>n.text).join(' ')}</p>}<div className="digest-sources">{selectedDigest.data.events[i].sources.map((s:Obj)=><a href={s.url} target="_blank" rel="noreferrer" key={s.id}>{s.source} <ArrowUpRight size={12}/><small>{fmt(s.published_at)} · {s.id}</small></a>)}</div></section>)}{selectedDigest.data.event_count<5&&<p className="hint">{selectedDigest.data.zero_events_reason}</p>}</article>}
    <div className="editor-footer"><span className={selectedDigest.validation[digestTab==='post'?'post_chars':'full_chars']>(digestTab==='post'?2000:4000)?'over-limit':''}>{editing?countCharacters(renderPlain(selectedDigest.data,editedItems,digestTab==='post'),selectedDigest.data.urls):selectedDigest.validation[digestTab==='post'?'post_chars':'full_chars']} / {digestTab==='post'?'2 000':'4 000'} знаков <small>без URL</small></span>{digestTab==='full'&&<button className="text-button" disabled={!canEdit} onClick={()=>{setEditedItems(JSON.parse(JSON.stringify(selectedDigest.data.items)));setEditing(!editing)}}>Редактировать</button>}</div></section><aside className="digest-rail"><section className="panel checks-card"><h3><ShieldCheck size={19}/> Проверки выпуска</h3>{selectedDigest.validation.checks.map((check:string)=><div className={"check-item "+(!selectedDigest.validation.passed?"warning":"")} key={check}>{selectedDigest.validation.passed?<CheckCircle2 size={15}/>:<AlertCircle size={15}/>}<span>{check}</span></div>)}{selectedDigest.validation.errors.map((error:string)=><div className="check-item warning" key={error}><AlertCircle size={15}/><span>{error}</span></div>)}<div className="review-note"><Eye size={17}/><p>Автоматические проверки не заменяют редактора. Проверьте оговорки и исходные фрагменты.</p></div></section><section className="panel"><div className="panel-head"><h3>Состав выпуска</h3><span className="badge neutral">{selectedDigest.data.event_count} / 5</span></div><div className="order-list">{selectedDigest.data.items.map((item:Obj,i:number)=><div key={item.event_id}><span>{i+1}</span><b>{item.title.text}</b><button className="icon-button" disabled={!canEdit||i===0} title="Поднять событие" onClick={()=>action(async()=>{const ids=selectedDigest.data.items.map((x:Obj)=>x.event_id);[ids[i-1],ids[i]]=[ids[i],ids[i-1]];const d=await patch('/digests/'+selectedDigest.id+'/draft',{event_ids:ids});setSelectedDigest(d)})}><ArrowUp size={14}/></button></div>)}</div></section><section className="panel export-card"><h3>Передать выпуск</h3><a className="btn wide" href={'/api/v1/digests/'+selectedDigest.id+'/export?format=eml'}><Mail size={16}/> Скачать письмо</a><button className="btn wide" disabled={!canEdit||selectedDigest.status!=='approved'} onClick={()=>setModal('send')}><Send size={16}/> Отправить по почте</button><p>На адрес активного подписчика после утверждения редактором.</p></section></aside></div>
   </>}</>}


   {view==='journal'&&<section className="panel"><div className="panel-head"><h2>Решения по материалам</h2>{run&&<div className="button-row"><a className="btn tiny" href={'/api/v1/runs/'+run.id+'/log?format=csv'}><Download size={15}/> CSV</a><a className="btn tiny" href={'/api/v1/runs/'+run.id+'/log?format=json'}>JSON</a></div>}</div>{run?.decisions?.length?<div className="table-wrap"><table><thead><tr><th>ID</th><th>Решение</th><th>Причина</th><th>Группа события</th><th/></tr></thead><tbody>{run.decisions.map((d:Obj)=><tr key={d.article_id}><td><code>{d.article_id}</code></td><td><Badge status={d.status}/></td><td><b className="reason-code">{d.reason_code}</b><small>{d.reason_text}</small></td><td><code>{d.event_group_ids.join(', ')||'—'}</code></td><td><button className="icon-button" onClick={()=>{setDetail(d);setModal('decision')}}><Eye size={16}/></button></td></tr>)}</tbody></table></div>:<Empty icon={History} title="Журнал пока пуст" text="После обработки здесь появится объяснение для каждой записи, включая пропуски и ошибки."/>}{run&&<div className="metrics-footer"><span>Модель: {run.metrics.model_identifiers?.join(', ')}</span><span>Запросы: {run.metrics.model_calls??'Недоступно'}</span><span>Токены: {run.metrics.tokens??'Недоступно'}</span><span>Стоимость: {run.metrics.cost??'Недоступно'}</span><span>Время: {run.metrics.duration_seconds} с</span></div>}</section>}

   {view==='schedules'&&<><div className="notice"><Clock size={17}/><span>Расписание создаёт черновики по МСК. Отправка выполняется после утверждения редактором.</span></div><section className="panel">{schedules.length?<div className="table-wrap"><table><thead><tr><th>Название</th><th>Каждый день, МСК</th><th>Следующий запуск</th><th>Последний запуск</th><th>Включено</th></tr></thead><tbody>{schedules.map(s=><tr key={s.id}><td><b>{s.name}</b><small>GigaChat</small></td><td>{String(s.hour).padStart(2,'0')}:{String(s.minute).padStart(2,'0')}</td><td>{fmt(s.next_run)}</td><td>{s.last_run?fmt(s.last_run):'Не запускался'}</td><td><label className="switch"><input type="checkbox" checked={s.enabled} onChange={e=>action(()=>patch('/schedules/'+s.id,{enabled:e.target.checked}))}/><span/></label></td></tr>)}</tbody></table></div>:<Empty icon={Clock} title="Расписание не настроено" text="Выберите набор и время ежедневной подготовки. Включение можно изменить в любое время."/>}</section></>}

   {view==='subscribers'&&<><div className="notice"><Lock size={17}/><span>Рассылка доступна активным подписчикам после утверждения выпуска. Адреса из публикаций не становятся получателями.</span></div><section className="panel">{subscribers.length?<div className="table-wrap"><table><thead><tr><th>Имя</th><th>Email</th><th>Тип</th><th>Активен</th></tr></thead><tbody>{subscribers.map(s=><tr key={s.id}><td>{s.name||'Не указано'}</td><td><b>{s.email}</b></td><td><Badge status="neutral">Подписчик</Badge></td><td><label className="switch"><input type="checkbox" checked={s.active} onChange={e=>action(()=>patch('/subscribers/'+s.id,{active:e.target.checked}))}/><span/></label></td></tr>)}</tbody></table></div>:<Empty icon={Users} title="Подписчики ещё не добавлены" text="Добавьте получателей. После утверждения выпуска его можно отправить по почте."/>}</section></>}

   {view==='settings'&&<div className="settings-grid"><section className="panel settings-panel"><div className="panel-head"><div className="giga-symbol">G</div><div><h2>GigaChat API</h2><p>Классификация, объединение, отбор и написание</p></div><Badge status={settings?.gigachat_configured?'passed':'needs_review'}>{settings?.gigachat_configured?'Ключ настроен':'Нет ключа'}</Badge></div><div className="settings-body"><div className="setting-row"><span>Scope</span><code>{settings?.scope||'GIGACHAT_API_PERS'}</code></div><label>Модель<select aria-label="Модель" value={settings?.model||''} onChange={e=>setSettings(s=>({...s,model:e.target.value}))}><option value="">Сначала проверьте подключение</option>{settings?.model&&!models.includes(settings.model)&&<option>{settings.model}</option>}{models.map(m=><option key={m}>{m}</option>)}</select></label><div className="button-row"><button className="btn" disabled={!canEdit||busy||!settings?.gigachat_configured} onClick={()=>action(async()=>{const r=await post('/settings/gigachat/test');setModels(r.models);notify('Подключение успешно. Доступно моделей: '+r.models.length);return r})}><RefreshCw size={15}/> Проверить подключение</button><button className="btn primary" disabled={!canEdit||!settings?.model||busy} onClick={()=>action(()=>patch('/settings',{gigachat_model:settings?.model}),'Модель сохранена')}>Сохранить модель</button></div><div className="config-note"><Lock size={17}/><p>Ключ хранится в закрытой конфигурации сервера и не передаётся в браузер.</p></div></div></section><section className="panel settings-panel"><div className="panel-head"><Mail size={23}/><div><h2>Почтовая рассылка</h2><p>Предпросмотр доступен без SMTP</p></div><Badge status="neutral">SMTP</Badge></div><div className="settings-body"><div className="setting-row"><span>SMTP</span><b>{settings?.smtp_configured?'Настроен':'Не настроен'}</b></div><button className="btn" disabled={!canEdit||busy||!settings?.smtp_configured} onClick={()=>action(()=>post('/settings/smtp/test'),'Подключение к почте проверено. Письмо не отправлялось.')}><RefreshCw size={15}/> Проверить почту</button><label>Дополнительные разрешённые адреса<textarea placeholder="reader@example.org" value={settings?.recipient_allowlist||''} onChange={e=>setSettings(s=>({...s,recipient_allowlist:e.target.value}))}/></label><button className="btn" disabled={!canEdit||busy} onClick={()=>action(()=>patch('/settings',{recipient_allowlist:settings?.recipient_allowlist||''}),'Allowlist сохранён')}>Сохранить адреса</button><div className="config-note"><Lock size={17}/><p>SMTP задаётся в закрытой конфигурации сервера. Получателей и утверждение выпуска контролирует редактор.</p></div></div></section><section className="panel settings-panel"><div className="panel-head"><Calendar size={23}/><h2>Правила выпуска</h2></div><div className="settings-body"><div className="setting-row"><span>Часовой пояс</span><b>Europe/Moscow</b></div><div className="setting-row"><span>Период</span><b>Последние 24 часа</b></div><div className="setting-row"><span>Границы</span><code>start &lt; date ≤ end</code></div><div className="setting-row"><span>События</span><b>От 0 до 5</b></div><div className="setting-row"><span>Текст / пост без URL</span><b>4 000 / 2 000 знаков</b></div></div></section><section className="panel settings-panel"><div className="panel-head"><Globe size={23}/><h2>Развёртывание</h2></div><div className="settings-body"><div className="setting-row"><span>Текущая среда</span><Badge status="passed">{settings?.app_env==='server'?'Сервер':'Локальная'}</Badge></div><div className="setting-row"><span>Адрес сайта</span><code>{settings?.public_base_url||data?.integrations?.public_base_url}</code></div><p className="hint">Состояние сервисов проверяется автоматически. Выпуски и материалы сохраняются в PostgreSQL.</p></div></section></div>}
   {!data&&<div className="loading-line"><Loader2 className="spin" size={19}/> Загрузка рабочего пространства…</div>}
  </main><footer className="app-footer"><span>КиберСводка · Проверяемые новости по ИБ</span><span>Ссылки и оригиналы сохраняются</span></footer></div>

  {toast&&<div className={'toast '+(toast.error?'error':'')} role="status">{toast.error?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>} {toast.message}<button aria-label="Закрыть уведомление" onClick={()=>setToast(null)}><X size={14}/></button></div>}
  {modal&&<div className="modal-backdrop" onClick={()=>setModal(null)}><section className={'modal '+(['article','evidence','test','job','decision'].includes(modal)?'large':'')} onClick={e=>e.stopPropagation()} role="dialog" aria-modal="true"><div className="modal-head"><h2>{({import:'Импорт материалов',manual:'Добавить материал',url:'Загрузить по ссылке',subscriber:'Новый подписчик',schedule:'Новое расписание',send:'Отправить письмо',article:'Исходная публикация',evidence:'Факты и исходные фрагменты',test:'Результат проверки',decision:'Решение по материалу',job:'Результат операции'} as Obj)[modal]}</h2><button className="icon-button" aria-label="Закрыть окно" onClick={()=>setModal(null)}><X size={20}/></button></div>
   {['import','manual','url','subscriber','schedule','send'].includes(modal)?<form className="modal-body" onSubmit={submitModal}>
    {modal==='import'&&<><label className="upload-zone"><Upload size={30}/><b>Выберите файл с публикациями</b><span>JSON · JSONL · CSV · TXT · HTML · DOCX · ZIP · до 20 МБ</span><input name="file" type="file" required accept=".json,.jsonl,.csv,.txt,.html,.htm,.docx,.zip"/></label><label>Название набора<input name="name" placeholder="Материалы организаторов"/></label><label>Сопоставление колонок CSV, JSON<textarea name="mapping" defaultValue="{}" placeholder={'{"Заголовок":"title","Дата":"published_at"}'}/></label><div className="two-cols"><label>Кодировка CSV/TXT<select name="encoding"><option value="utf-8-sig">UTF-8</option><option value="cp1251">Windows-1251</option></select></label><label>Часовой пояс<input type="checkbox" name="assume_moscow"/><span>Даты без зоны считать МСК (явное правило импорта)</span></label></div><details><summary>Метаданные для TXT / HTML / DOCX</summary><div className="two-cols"><label>ID<input name="id"/></label><label>Источник<input name="source"/></label></div><label>Заголовок<input name="title"/></label><label>URL<input name="url" type="url"/></label><label>Дата публикации, МСК<input name="published_at" type="datetime-local"/></label></details><p className="hint">Для TXT, HTML и DOCX извлекается текст. Дату, ID, источник и URL добавьте в JSON или через ручной ввод: они не будут придуманы.</p></>}
    {modal==='manual'&&<><div className="two-cols"><label>ID<input name="id" required/></label><label>Источник<input name="source"/></label></div><label>Заголовок<input name="title"/></label><label>URL исходной публикации<input name="url" type="url"/></label><label>Дата публикации, МСК<input name="published_at" type="datetime-local"/></label><label>Исходный текст<textarea name="text" rows={7}/></label></>}
    {modal==='url'&&<><label>URL публикации<input name="url" type="url" required placeholder="https://…"/></label><label>Название источника<input name="source"/></label><p className="hint">Получение учитывает robots.txt. Частные адреса, служебные порты и опасные redirects блокируются.</p></>}
    {modal==='subscriber'&&<><label>Имя<input name="name"/></label><label>Email подписчика<input name="email" type="email" required/></label><p className="hint">Активный подписчик сможет получать утверждённые выпуски.</p></>}
    {modal==='schedule'&&<><label>Название<input name="name" required defaultValue="Ежедневный дайджест"/></label><label>Набор<select name="dataset_id" required defaultValue={datasetId}><option value="sources">Согласованные источники: новый сбор</option>{data?.datasets?.map((d:Obj)=><option key={d.id} value={d.id}>{d.name}</option>)}</select></label><label>Время, МСК<input name="time" type="time" defaultValue="09:00" required/></label><p className="hint">Расписание создаётся выключенным. Включите его после проверки настроек.</p></>}
    {modal==='send'&&<><label>Email получателя<input name="recipient" type="email" required/></label><p className="hint">Укажите активного подписчика или адрес, разрешённый в настройках рассылки.</p></>}
    <div className="modal-footer"><button type="button" className="btn" onClick={()=>setModal(null)}>Отмена</button><button className="btn primary" disabled={busy}>{busy?<Loader2 className="spin" size={16}/>:<Check size={16}/>} {modal==='send'?'Отправить тест':modal==='url'?'Загрузить':'Сохранить'}</button></div></form>:<div className="modal-body">
    {modal==='article'&&detail&&<><span className="outline-pill">ID {detail.id}</span><h3>{detail.title}</h3><p>{detail.source} · {fmt(detail.published_at)}</p><a className="text-button" href={detail.url} target="_blank" rel="noreferrer">Исходная ссылка <ArrowUpRight size={14}/></a><pre className="source-text">{detail.text||'Основной текст отсутствует'}</pre><details><summary>Оригинальные метаданные</summary><pre>{JSON.stringify({...detail,text:undefined,source_snapshot_html:undefined},null,2)}</pre></details></>}
    {modal==='evidence'&&detail?.claims.map((c:Obj)=><div className="fact-row" key={c.claim_id}><ShieldCheck size={18}/><div><h3>{c.text}</h3><blockquote>{c.quote}</blockquote><small>{c.article_id} · offsets {c.start_offset}–{c.end_offset} · {c.certainty}</small></div></div>)}
    {['decision','job'].includes(modal)&&<pre>{JSON.stringify(detail,null,2)}</pre>}
    {modal==='test'&&detail&&<><Badge status={detail.status}/><p>{detail.failures?.join('; ')||'Проверяемые условия выполнены.'}</p><details open><summary>Входные данные</summary><pre>{JSON.stringify(detail.input,null,2)}</pre></details><details><summary>Фактический ответ и настройки</summary><pre>{JSON.stringify(detail.output,null,2)}</pre></details><p className="hint">{fmt(detail.started_at)}</p></>}
   </div>}
  </section></div>}
 </div>
}
